CREATE TABLE IF NOT EXISTS maintenance_reliability_executive_governance_effectiveness_snapshot (snapshot_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, period_key TEXT NOT NULL, escalation_count INTEGER NOT NULL DEFAULT 0, resolved_escalation_count INTEGER NOT NULL DEFAULT 0, overdue_escalation_count INTEGER NOT NULL DEFAULT 0, evidence_complete_count INTEGER NOT NULL DEFAULT 0, evidence_gap_count INTEGER NOT NULL DEFAULT 0, action_count INTEGER NOT NULL DEFAULT 0, completed_action_count INTEGER NOT NULL DEFAULT 0, effective_action_count INTEGER NOT NULL DEFAULT 0, ineffective_action_count INTEGER NOT NULL DEFAULT 0, resolution_rate NUMERIC NOT NULL DEFAULT 0, effectiveness_rate NUMERIC NOT NULL DEFAULT 0, governance_effectiveness_score NUMERIC NOT NULL DEFAULT 0, assessment TEXT NOT NULL DEFAULT 'NO_BASELINE', status TEXT NOT NULL DEFAULT 'OPEN', recommendation TEXT, created_by TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(organization_id,entity_id,period_key));
